using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Temporal;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
public abstract class TemporalRuleBase: AstronomyKnowledgeValidationRule<AstronomyTemporalPatternPayload>{protected static AstronomyKnowledgeValidationIssue Issue(string c,string m,string p,string r)=>new(c,AstronomyKnowledgeValidationSeverity.Error,m,p,r,AstronomyKnowledgeDomain.Temporal,AstronomyKnowledgePayloadFamily.TemporalCycle); public override AstronomyKnowledgeDomain Domain=>AstronomyKnowledgeDomain.Temporal; public override AstronomyKnowledgePayloadFamily Family=>AstronomyKnowledgePayloadFamily.TemporalCycle;}
public sealed class AstronomyTemporalPatternValidationRule:TemporalRuleBase{public const string Id="temporal.pattern.integrity"; public override string RuleId=>Id; public override int Order=>100; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyTemporalPatternPayload p,AstronomyKnowledgeValidationContext c){if(!Enum.IsDefined(p.Pattern.Kind)) yield return Issue(AstronomyTemporalValidationCodes.PatternKindInvalid,"Pattern kind must be defined.","$.pattern.kind",RuleId); if(c.Mode==AstronomyKnowledgeValidationMode.Strict&&(string.IsNullOrWhiteSpace(p.Pattern.Name)||string.IsNullOrWhiteSpace(p.Pattern.Summary))) yield return Issue(AstronomyTemporalValidationCodes.PatternTextIncomplete,"Strict temporal validation requires name and summary.","$.pattern",RuleId);}}
